const fs = require("fs");
const path = require("path");
const { withDangerousMod, withEntitlementsPlist, withXcodeProject } = require("@expo/config-plugins");

// Notification Service Extension that decrypts Secret Chat pushes on the
// phone (files/NotificationService.swift). A config plugin rather than a
// hand edit because ios/ is regenerated by `expo prebuild`.
//
//  - copies files/ into ios/NotificationService/ (Info.plist gets the app's
//    version and build number — App Store Connect rejects an extension
//    whose versions differ from its app's);
//  - adds the app-extension target, embeds it in the app;
//  - gives the app and the extension a shared keychain group, through which
//    the app hands over Secret Chat session keys (src/lib/notificationKeys.ts).

const TARGET = "NotificationService";
const TEAM_ID = "P37BNY7C4J";
const SOURCES = ["NotificationService.swift", "SecretBox.swift", "tweetnacl.c", "randombytes.c"];
const OTHER_FILES = ["tweetnacl.h", "NotificationService-Bridging-Header.h", "NotificationService.entitlements"];

function sharedKeychainGroup(config) {
  return `$(AppIdentifierPrefix)${config.ios.bundleIdentifier}.shared`;
}

function withExtensionFiles(config) {
  return withDangerousMod(config, [
    "ios",
    (config) => {
      const source = path.join(__dirname, "files");
      const destination = path.join(config.modRequest.platformProjectRoot, TARGET);
      fs.mkdirSync(destination, { recursive: true });
      for (const file of [...SOURCES, ...OTHER_FILES]) {
        fs.copyFileSync(path.join(source, file), path.join(destination, file));
      }
      const plist = fs
        .readFileSync(path.join(source, "Info.plist"), "utf8")
        .replace("__VERSION__", config.version)
        .replace("__BUILD_NUMBER__", config.ios.buildNumber)
        // Spelled out with the team prefix: $(AppIdentifierPrefix) is only
        // filled in when Xcode signs, and src/lib/notificationKeys.ts writes
        // to this exact name.
        .replace("__SHARED_KEYCHAIN_GROUP__", `${TEAM_ID}.${config.ios.bundleIdentifier}.shared`);
      fs.writeFileSync(path.join(destination, "Info.plist"), plist);
      return config;
    },
  ]);
}

function withAppKeychainGroups(config) {
  return withEntitlementsPlist(config, (config) => {
    // The app's own group stays FIRST: it is the default for every keychain
    // write without an explicit group, so existing items (the E2E identity
    // keys) keep being read and written exactly where they already live.
    const groups = [`$(AppIdentifierPrefix)${config.ios.bundleIdentifier}`, sharedKeychainGroup(config)];
    const existing = config.modResults["keychain-access-groups"] ?? [];
    config.modResults["keychain-access-groups"] = [...new Set([...groups, ...existing])];
    return config;
  });
}

function withExtensionTarget(config) {
  return withXcodeProject(config, (config) => {
    const project = config.modResults;
    if (project.pbxTargetByName(TARGET)) {
      // Already there from an earlier prebuild: only keep its versions in
      // step with the app's.
      setExtensionBuildSettings(project, {
        CURRENT_PROJECT_VERSION: config.ios.buildNumber,
        MARKETING_VERSION: config.version,
      });
      return config;
    }

    // A single-target Expo project has neither section yet; addTarget's
    // dependency wiring expects both.
    const objects = project.hash.project.objects;
    objects.PBXTargetDependency = objects.PBXTargetDependency ?? {};
    objects.PBXContainerItemProxy = objects.PBXContainerItemProxy ?? {};

    const group = project.addPbxGroup([...SOURCES, ...OTHER_FILES, "Info.plist"], TARGET, TARGET);
    const mainGroup = project.getFirstProject().firstProject.mainGroup;
    project.addToPbxGroup(group.uuid, mainGroup);

    // Also embeds the product into the app (a Copy Files phase on the first
    // target, which is the app) and makes the app depend on it.
    const target = project.addTarget(TARGET, "app_extension", TARGET, `${config.ios.bundleIdentifier}.${TARGET}`);
    project.addBuildPhase(SOURCES, "PBXSourcesBuildPhase", "Sources", target.uuid);
    project.addBuildPhase([], "PBXResourcesBuildPhase", "Resources", target.uuid);
    project.addBuildPhase([], "PBXFrameworksBuildPhase", "Frameworks", target.uuid);
    tidyFileReferences(project, [...group.pbxGroup.children.map((child) => child.value), target.pbxNativeTarget.productReference]);
    renameEmbedPhase(project);

    setExtensionBuildSettings(project, {
        APPLICATION_EXTENSION_API_ONLY: "YES",
        CLANG_ENABLE_MODULES: "YES",
        CODE_SIGN_ENTITLEMENTS: `${TARGET}/${TARGET}.entitlements`,
        CODE_SIGN_STYLE: "Automatic",
        CURRENT_PROJECT_VERSION: config.ios.buildNumber,
        DEVELOPMENT_TEAM: TEAM_ID,
        INFOPLIST_FILE: `${TARGET}/Info.plist`,
        IPHONEOS_DEPLOYMENT_TARGET: "15.1",
        MARKETING_VERSION: config.version,
        SWIFT_OBJC_BRIDGING_HEADER: `"${TARGET}/${TARGET}-Bridging-Header.h"`,
        SWIFT_VERSION: "5.0",
        TARGETED_DEVICE_FAMILY: config.ios.supportsTablet ? `"1,2"` : "1",
    });
    project.addTargetAttribute("DevelopmentTeam", TEAM_ID, target);
    return config;
  });
}

function setExtensionBuildSettings(project, values) {
  const configurations = project.pbxXCBuildConfigurationSection();
  for (const key of Object.keys(configurations)) {
    const settings = configurations[key].buildSettings;
    const name = String(settings?.PRODUCT_NAME ?? "").replace(/"/g, "");
    if (name === TARGET) Object.assign(settings, values);
  }
}

// The xcode library doesn't know .c files (it marks them "unknown", which
// Xcode won't compile), writes unset fields out as the literal `undefined`,
// and makes a build file for every group member, headers and plists
// included. Fixes all three for the references this plugin added.
function tidyFileReferences(project, refIds) {
  const references = project.pbxFileReferenceSection();
  for (const id of refIds) {
    const reference = references[id];
    if (!reference) continue;
    for (const field of Object.keys(reference)) {
      if (reference[field] === undefined || reference[field] === "undefined") delete reference[field];
    }
    const file = String(reference.path ?? "").replace(/"/g, "");
    if (file.endsWith(".c")) reference.lastKnownFileType = "sourcecode.c.c";
    if (file.endsWith(".entitlements")) reference.lastKnownFileType = "text.plist.entitlements";
    if (reference.lastKnownFileType === "unknown") delete reference.lastKnownFileType;
  }
  const keep = new Set(SOURCES);
  const buildFiles = project.pbxBuildFileSection();
  for (const key of Object.keys(buildFiles)) {
    const buildFile = buildFiles[key];
    if (typeof buildFile !== "object" || !refIds.includes(buildFile.fileRef)) continue;
    const file = String(references[buildFile.fileRef]?.path ?? "").replace(/"/g, "");
    if (file.endsWith(".appex") || keep.has(file)) continue;
    delete buildFiles[key];
    delete buildFiles[`${key}_comment`];
  }
}

function renameEmbedPhase(project) {
  const phases = project.hash.project.objects.PBXCopyFilesBuildPhase ?? {};
  for (const key of Object.keys(phases)) {
    if (typeof phases[key] === "object" && phases[key].dstSubfolderSpec === 13) {
      phases[key].name = '"Embed Foundation Extensions"';
      phases[`${key}_comment`] = "Embed Foundation Extensions";
      for (const phaseRef of project.getFirstTarget().firstTarget.buildPhases) {
        if (phaseRef.value === key) phaseRef.comment = "Embed Foundation Extensions";
      }
    }
  }
}

module.exports = function withNotificationService(config) {
  config = withExtensionFiles(config);
  config = withAppKeychainGroups(config);
  config = withExtensionTarget(config);
  return config;
};
